[ExtensionOf(formControlStr(MCRSalesQuickQuote, isSalesItem))]
final class NDXMCRSalesQuickQuote_fctr_Extension
{
}

Method.Source:
/// <summary>
/// modified
/// </summary>
/// <returns>true or false</returns>
public boolean modified()
{
    FormRun formRun;
    FormObjectSet fos;

    int tableid;

    int counter, numberOfDataSources;

    boolean ret;

    ret = next modified();
    formRun = this.formRun();

    numberOfDataSources = formRun.dataSourceCount();

    for(counter = 1; counter < numberOfDataSources; counter++)
    {
        fos = formRun.dataSource(counter);
        tableid = tableName2Id(fos.name());
        if(tableid == tablenum(InventItemDimTmpFilter))
        {
            fos.research();
            break;
        }
    }

    return ret;
}
